quests[48620] = { id = 48620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greater Invasion Point: Mistress Alluradel" }
quests[48622] = { id = 48622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vanishing Lord", description = "Unfortunately, we don't have any contacts within House Waycrest, so our efforts in Drustvar will have to start from the ground up.\n\nWe have arranged for a ferry to take you to Fallhaven - a farming village in eastern Drustvar. The mayor there, Cyril White, is a longtime friend of the Proudmoores, and I think he can help us get in touch with someone from the house.\n\nI hope you can get to the bottom of their absence, {name}. Their martial might is invaluable to the Kul Tiran fleet.", completion = "<The effigy is protected by powerful magic. \n\nIt seems it will take more than brute force to break this curse.>", objectives = "Meet with Cyril White in Fallhaven in Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
