quests[48631] = { id = 48631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing Krokuun", description = "Legion patrols are an ever-present threat. Eradicate demon commanders you encounter, and I will grant you a ridgestalker guide.", objectives = "Slay 4 Rare Elites on Krokuun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48632] = { id = 48632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void Extract", description = "The void calls to its own. \n\nWhen they are destroyed, powerful creatures of shadow leave behind vast amounts of undiluted void. It's lure is powerful enough to draw out the noxious influence polluting my brethren. Not all survive the purge, but the alternative is worse than death - you've seen the voidscarred roaming Oranaar.\n\nDestroy a powerful agent of shadow, collect its essence, and bring it to me. I will use it draw out the corruption.", sourceObjective = "Gather an Orb of Undiluted Void.", sourceObjectiveStatus = "unverified-source-field" }
quests[48634] = { id = 48634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Further Supplying Krokuun", description = "This desolate place offers little for my people. Every hour is spent scraping together enough to survive. If I had more supplies, I could offer you another ridgestalker.\n\nWhat say you, offworlder?", progress = "You seek the aid of another ridgestalker?", completion = "You must value our aid greatly, to part with such a bounty.", objectives = "Collect 900 Order Hall Resources.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48635] = { id = 48635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Void Inoculation", description = "All entities touched by shadow leave behind traces of void when they are defeated, If you collect enough in your travels through the city, return to me, and I will distill it into its undiluted form. \n\nWe can save more of my kin.", progress = "Many of my brethren are deeply touched by shadow. It will take a tremendous effort to free them. Will you help?", completion = "I am humbled by your generosity.", objectives = "Collect 100 Fragments of Condensed Void.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48636] = { id = 48636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fueling the Antoran Campaign", description = "The Legion requires raw materials from conquered words to fuel their crusade. Travel through Legion portals, destroy demons you encounter, and deny them the resources required to maintain their war machine.", progress = "War is costly work. Have you gathered additional supplies for our efforts here?", completion = "Another lightforged to fight alongside your forces.", objectives = "Complete 10 Invasion Points.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
