quests[48653] = { id = 48653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bejeweled Prison", description = "<As you gaze into the strange gem you feel a sudden need to travel into the swamps of Nazmir and return the gem to it's rightful resting place, wherever that may be.>", objectives = "Return the Restored Eye of Eternity to its resting place within the Dreadmire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48654] = { id = 48654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beneath Oronaar", description = "The krokul we found beneath Oranaar did not wish to leave. Could you speak with him, {name}? Convince him to board the Vindicaar.", completion = "I told the others; I will not abandon my people. I must remain here, but maybe you can help? I have discovered a way to purge the shadow from the void-addled.", objectives = "Speak with the krokul beneath Oranaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48655] = { id = 48655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chef's Apprentice", description = "<Sezahjin rummages through his cooking ingredients in frustration.>\n\nWhere is Junji? I sent him to scavenge for vulture eggs, but he hasn't returned.\n\n<Sezahjin pauses for a moment.>\n\nHe was just going on about de size of saurolisk eggs, but those oversized lizards are far too dangerous for a boy! He can't possibly be so foolish...\n\nIf he has gone to de saurolisk breeding grounds... he may already be dead. Please find him before it's too late!", completion = "You can't fool me, saurolisk! I know you're out dere waiting to eat me! Oh wait... you're a grown up! Please, get me out of here! Help!", objectives = "Locate Junji.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48656] = { id = 48656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Savage Saurolisks", description = "Please, help me! I'm trapped in dis box and I can't make it out alone!\n\nI came here to collect eggs. I knew it was a bad idea, but I thought I could sneak around and grab de eggs before de saurolisks noticed.\n\nI was wrong...\n\nI hid underneath dis crate to avoid being eaten!\n\nCan you clear out de saurolisks and tell me when it's safe to come out?\n\nPlease, don't leave me here!", progress = "Are de saurolisks gone yet?", completion = "De saurolisks are all gone and it's safe to come out? Thank you so much! I never thought I'd make it out of here alive!", objectives = "Slay 8 Scaleclaw Saurolisks in the Arid Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48657] = { id = 48657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Might Be Delicious", description = "Saurolisk eggs are de most delicious eggs in de desert!\n\nI mean, I've never tried dem myself... but look at de size of them! Dey're huge! Bigger is better, right?\n\nIf I go back to camp empty handed, Sezahjin is going to kill me! We have to get some of those eggs!\n\nYou sound a lot older and stronger than I am. Gather up de eggs so we can take dem back for everyone to eat.\n\nDon't worry about me, I'll wait for you here. It's not like I'm going anywhere...", progress = "Do you have de saurolisk eggs?", completion = "You have de eggs! Be careful not to break dem... just roll dem under da box... gently... gently now...", objectives = "Gather 10 saurolisk eggs from the Arid Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48662] = { id = 48662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short Fuses" }
