quests[48667] = { id = 48667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48668] = { id = 48668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightforged Beacon: City Center", description = "Hail, friend!\n\nCaptain Fareeya sent us ahead to secure this area. We were just about to call down a beacon and report back to the Vindicaar.\n\nWe would be honored if you would help us complete our mission.\n\nThe signal beacon just needs a light touch. The Grand Artificer will do the rest.", progress = "Grand Artificer Romuul is a reliable soul. We would be lost on this planet without him.", completion = "This beacon will be added to the Navigation Console.\n\nA contingent of the Army of the Light will remain to hold this location for future use.", objectives = "Activate the Vindicaar Beacon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48669] = { id = 48669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urok, Terror of the Wetlands", description = "You! You can help me!\n\nI know, Sur'jan, <he/she> looks like a {class}, but I know we can trust <him/her>.\n\nUrok, de terror of de wetlands, is undead now. We have to put it down before it tries to destroy dis entire place.\n\nJust give me a minute, and you will see dat Urok is bad news.\n\nShhh, Sur'jan, dey gonna see, dey are all gonna see!", progress = "Just give me a chance and you'll see!", completion = "Now you see? We must beat Urok. I know how to do it, but I can't do it alone.", objectives = "See Urok, Terror of the Wetlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48670] = { id = 48670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runaway Rider", description = "Lord Norwington demanded I take Eddie out riding in the woods, but I knew it was too soon! I just knew it!\n\nWe've got to go find him. Meet me across the river!", completion = "How could this get any worse?\n\nThe troggs have captured Eddie!", objectives = "Meet Melissa Kenny near Mistfall Cleft.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
