quests[48699] = { id = 48699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sneaking into Zalamar", description = "I know you might think nothing has changed, but trust me, de voodoo worked... I think.\n\nYou should transform into one of de blood trolls when you are near Zalamar, one of their villages.\n\nJo'chunga should be dere somewhere, most likely near a large gathering of blood trolls.\n\nFind Jo'chunga and tell him I have sent you, den see what he knows about de situation dere.", completion = "Good, we will be safe in here. I am happy dat you are here, because I am not able to stop dis alone.", objectives = "Sneak into Zalamar to find Jo'chunga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
