quests[48715] = { id = 48715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akunda Awaits", description = "I've spoken to every troll out here, asking if they've seen Rakera. As you might have guessed, Akunda is de only name dey know. \n\nLet's hope someone within de temple will be able to tell us something useful.", completion = "Dis is Rakera. I have no doubt. But for some reason, she does not remember me... or herself, it would seem...", objectives = "Investigate the Temple of Akunda.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
