quests[48751] = { id = 48751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48752] = { id = 48752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Need For Coal", description = "Ah! {name}! Just the person I was hoping to see!\n\nI was just getting ready to smelt some monelite down into ingots, but I noticed my coal supply was running low.\n\nWell, I mean... I have coal, yes, but I prefer using Ashvane Coal. It puts out less smoke and burns hotter, so I need less of it.\n\nIf you can  get some Ashvane Coal from the Ashvane Foundry south of here, I'd be more than willing to give you a couple pointers for mining monelite. Deal?", progress = "Have you gone to the foundry yet?", completion = "Thanks! You can never be too careful when it comes to breathing thick clouds of smoke from burning coal and molten metal.\n\nNow I owe you a lesson about monelite. Let's see, what to teach...\n\nWhen you're mining monelite, instead of chipping away at the rock, try using the pick to pierce the metal, and pull all of it away from the rock like it was taffy.", objectives = "Collect 9 handfuls of Ashvane Coal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48753] = { id = 48753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergency Transplants", description = "With everything that's been happening over in Drustvar, there's been a sudden surge of wildlife in the sound. Normally, I wouldn't care, but they've been eating all the riverbud!\n\nIf things don't improve soon, we could try thinning their numbers so they don't consume everything, but I'll consider that the last resort.\n\nInstead, could you go plant some of these seeds to produce additional food for them?", progress = "Have you planted the seeds yet?", completion = "I can't thank you enough! Riverbud is absolutely critical to the wildlife here. Regardless, I said I'd teach you if you helped out, and I'll ever be true to my word.\n\nThe biggest mistake that most herbalists out here do is allow the riverbuds to blow out when harvested.\n\nWhen you go to pick riverbud, you can't just rip them off the stem, or all the water will spill out. Instead, give them a twist first so they pinch the stem closed. Try it out!", objectives = "Plant 10 Riverbud Seeds in rivermud.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48754] = { id = 48754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking The Food Chain", description = "The extra riverbud you planted has helped, but it's not enough.  Some of the local wildlife are consuming the riverbud before they mature. The more riverbud that is eaten, the less we have for our own needs.\n\nThe largest group of young riverbud consumers are the turtles.\n\nIf the riverbud becomes a threatened species, we'll need to regulate harvesting it. Instead, go thin the number of the turtles in the area.\n\nDo that and I'll teach you everything I know about riverbud.", completion = "Good work, {name}. I can sleep soundly now that those turtles won't be gobbling up all of our precious riverbud.\n\nIf I recall correctly, I offered to teach you how to collect riverbud more effectively as thanks for you doing your part.\n\nWell, the secret to riverbud is that there are a couple extra bulbs in the root system. Just pull it by the coil firmly with steady pressure.", objectives = "Kill 15 Freshwater Snapper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48755] = { id = 48755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pollen Punching", description = "What I think happened is that some creature lapped up all the pollen with it's tongue.\n\nWhile I'm curious as to what creature could have done this, I doubt it matters. I believe we can safely reproduce this without needing any sort of rare or dangerous reagents.\n\nNext time you find a siren's sting, simply try wetting your glove so the pollen will stick to it. Water, wine, spit... It shouldn't matter.You will learn:", objectives = "Collect 12 Heaping Handfuls of Damp Pollen from siren's sting.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48756] = { id = 48756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Here In Spirit", description = "Hey, {name}, how would you feel about doing some legwork for a favor?\n\nWe have a tradition here in Kul Tiras, that during a celebration, be it funeral, wedding, or birthday, we incorporate star moss into the decorations. We do that so those who are no longer amongst the living can be here in spirit.\n\nWith the recent fighting, my stores are near empty due to the number of funerals we've had.\n\nIf you bring me fresh star moss to restock my supply, I'll share a secret on how to get more from each star moss.", progress = "There was a funeral the other day, seem to be more and more as of late. Any chance you gathered that star moss I asked for?", completion = "I appreciate you doing this, {name}. It's been hard to get out and gather anything myself, but the war doesn't wait for me.\n\nAs for that favor, how about a secret to harvesting star moss, something no one else would teach you?\n\nThe thing about star moss is that its magic is sensitive to emotions. When you go to harvest, clear your mind and think of those you've lost. That feeling of loss, reverence, and the joy they once brought will keep the bloom from wilting. That is why we use it for celebrations.", objectives = "Harvest 10 Fresh Star Moss.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48757] = { id = 48757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghost Busting", description = "I hate to ask this of you, but are you available for some more grunt work? I'd do it myself, but this seems beyond my capabilities.\n\nRemember how I told you we use star moss to allow those no longer living to join us for a special day?\n\nYeah, well, sometimes once they show up, they don't want to leave.  There is a spirit on the other side that is lashing out, harming those it should be protecting.\n\nTake this smoldering star moss and cleanse the area until you find the offender and help them move on.", progress = "Have you banished the spirit yet?", completion = "I can't thank you enough, {name}. Now that the spirit has been been put to rest, I'll send word to the family so they can get back to their normal lives.\n\nOnce again, you've proved that I can rely on you. If you swear to tell no one, I'll tell you the best kept secret of star moss.\n\nThis is going to sound crazy, but engage it. Talk to it, sing, hum, anything. I'm not sure why, but since I started I've noticed one or two extra flowers will bloom before my eyes!", objectives = "Put the Angry Spirit to rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48758] = { id = 48758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disgustingly Damp Flower", description = "Rummaging for pollen as usual, you use the harvesting technique you learned from the bees.  However, when you pull your hand away from the flower, you find that there is no pollen on your gloves.\n\nLooking inside the swirl of petals, despite it being a mature flower, you see that there is no pollen at all within it.  Upon closer inspection you see that the flower is filled with a viscous liquid.  Could the flower have done this?\n\nWhile unpleasant to touch, you carefully pluck the flower to show Declan.", completion = "Curious. There's no pollen at all? Can't say that I've heard of a plant doing that before.\n\nHmmmmmmmmm�\n\nWhat I think we have here is a more effective way of harvesting pollen than that of the bees.", objectives = "Bring the Disgustingly Damp Flower to Declan Senal.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48759] = { id = 48759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akunda's Bite - Rank 2 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.You will learn:", objectives = "Find someone on Argus who might be able to train you on how to handle Astral Glory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48760] = { id = 48760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akunda's Bite - Rank 3 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.You will learn:", objectives = "Find someone on Argus who might be able to train you on how to handle Astral Glory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48761] = { id = 48761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiderphobia", description = "You're no stranger to monster fighting, right?\n\nThe other day I found a spider just outside my house. Nothing out of the ordinary, except it was the SIZE OF A HORSE!\n\nTwenty-five minutes of screaming and pick-axeing later and I had managed to kill it.\n\nI spoke with one of the guards, and he said that there was a huge nest of them just over the hill to the northwest.\n\nIf you can slay them or whatever you do, I'll teach you a secret to mining monelite. Otherwise, I'm going to have to move.", progress = "I can't stand spiders.\n\n<Myra shudders.>\n\nHave you dealt with them yet?", completion = "I'm glad to see you made it back in one piece. I'm tempted to ask how it went, but frankly, thinking about it has been causing me quite a bit of anxiety.\n\nIf you don't mind, I'm going to distract myself from the thought with a lesson.\n\nYou've probably noticed that monelite is really maleable, right? You can use that, even before smelting it.\n\nBy using your pick to deform the metal while it's still in the vein, you can heat it up and get a bigger haul using the other technique I taught you.", objectives = "Kill 8 Enthralled Mossfangs and 15 Mossfang Egg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48762] = { id = 48762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet Sweetflower", description = "It looks like you've become familiar with the plants around here. There's a flower that grows in the snowy parts of the continent, but I can't tell you much else about it.  Can't stand being cold.\n\nHowever, if you're interested in learning more, I know of someone who may be able to teach you.\n\nHer name's Xun Xun Sweetflower, and last I heard she set up shop on the outskirts of Anyport over in Drustvar.  Tread carefully, though, that area is crawling with Irontide Raiders.", completion = "Oh, you'd like to learn about harvesting winter's kiss?  Well that's very fortunate, for both of us...", objectives = "Find Xun Xun Sweetflower in Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48763] = { id = 48763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Frigid Boon", description = "While harvesting this winter's bite, you managed to pluck the flower without breaking any petals, a feat you had not accomplished before.\n\nTaking a quick mental note of every detail about yourself and your surroundings, one point sticks out to you.\n\nThe heat from your breath appears to have made the petals supple enough to bend instead of break. You also believe that this may be a way to prevent the flower from activating its defensive cold blast.\n\nIf that is the case, it could be extremely useful.You will learn:", objectives = "Harvest 10 winter's kiss without taking cold damage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48764] = { id = 48764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Pick a Fight", description = "Hey, you're not busy, right? I could use your help.\n\nYa see, I was out mining in Stormsong Valley, when this huge, two-headed monstrosity started chasing after me!\n\nI ran away, but I was back in Boralus when I realized I dropped my favorite mining pick!\n\nI know this may sound stupid, but if you could get it back for me I'd be grateful.\n\nYou don't need to do something crazy, like fight them. Instead, sneak by them and grab it.\n\nI'll show you a trick to mining monelite seams for your troubles.", progress = "Did you get my mining pick back?", completion = "You're a life saver! Well, a livelihood saver!\n\nAs for that trick I had mentioned: Don't bother using a pick to separate the rock from the ore when pulling it from a monelite seam.\n\nIf the ore is big enough, once you remove it from the earth, you can peel the metal back and remove the rocks by hand.", objectives = "Retrieve Myra's Favorite Mining Pick.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48765] = { id = 48765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aromatic Pollen - Rank 2 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.You will learn:", objectives = "Find someone on Argus who might be able to train you on how to handle Astral Glory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48766] = { id = 48766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aromatic Pollen - Rank 3 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.You will learn:", objectives = "Find someone on Argus who might be able to train you on how to handle Astral Glory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48767] = { id = 48767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seams Familiar", description = "You find a necklace in the shape of an anchor with the name \"Cabot\" etched in a banner.\n\nThe name immediately brings up Myra Cabot, the mining trainer in Boralus.\n\nThe condition of the necklace makes it look like it has been well maintained. She probably wants it back.", completion = "By the Light! I thought I lost it forever!\n\nThis used to belong to my great grandfather.\n\n<Myra clutches the necklace close to her heart for a moment as a tear runs down her cheek. After a moment, she looks around, shaking her head.>\n\nNothing here can remotely repay this. It's not much, but I can show you how to get the most out of mining monelite seams.\n\n<Myra spends the next several minutes explaining several techniques to increase the amount of monelite mined from a seam.>", objectives = "Return the Lost Necklace to Myra Cabot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48768] = { id = 48768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brined Justice", description = "{name}, I just got word that one of our ships was attacked and a large amount of storm silver stolen!\n\nThe sacred materials can't be replaced. Once it is blessed by the seapriest, it is buried underwater for a year!\n\nFrom what I heard, a group of pirates followed the ship to see where the metal was buried on the sea floor before killing the crew and taking her cargo.\n\nKill the pirates and get back that metal.", progress = "Damn those pirates!\n\nHave you recovered the bars?", completion = "Ah!  This is fantastic news! I will have someone run these out to the docks right away.\n\nI was starting to fear that they may have gotten you, too.\n\nThat said, you have avenged my people.  In exchange, let me show you the finer points of harvesting storm silver.\n\n<Myra takes the next several minutes to explain what she knows about harvesting storm silver deposits.>", objectives = "Collect 100 Stolen Storm Silver Bars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48769] = { id = 48769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Mementos", description = "I have a task that I can't really trust to anyone else, and I feel you could handle it with the reverence it deserves.\n\nAn old friend of mine came to me today, bringing a wilted sea stalk flower with her. Her husband was on a ship south east of Freehold. I'm not sure if it was pirates, the Horde, or a squall, but she said she didn't want revenge, just closure.\n\nIf you could get her something to remember him by, I'll tell you everything I know about sea stalks, and you'd have my gratitude.", progress = "Have you found any of his personal effects?", completion = "I can't thank you enough for this.\n\nDeath seems to always haunt this land, but it's sting is somewhat lessened if we can still hold on to the memories of those departed. I'll need to get some fresh star moss for the funeral, but I'd prefer to do that myself.\n\nSadly, there isn't much left I can teach you about sea stalk. Let's see... something to help... ah, yes!\n\nTo help you get the most of each plant, instead of cutting it off, carefully pull it out of the sand and tear off the roots.", objectives = "Search through patches of sea weed to find a memento of the lost sailor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48770] = { id = 48770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Three Sheets to the Wind", description = "Hey, {name}.  Now isn't a great time for me.\n\nIf you're interested in learning, you could talk to Franklin, my old apprentice. He used to be a damn fine miner, but now he's just a washed up drunk. You can find him asleep on the docks.\n\nI don't remember what he drinks, but if you bring him something he's sure to at least try it. He'll talk if he likes it.\n\nTalk to Harold Atkey, the bartender, he's sells a variety of drinks, I'm sure one of them is his choice.", progress = "<Myra's former apprentice, Franklin drunkenly stares at you.>\n\nI ain't talkin'.... 'less you got a drink.", completion = "<Franklin rambles almost incoherently, explaining the mechanics of mining storm silver from a seam>\n\n... and that is how you... get the most of mining... Zzz...\n\n<As Franklin drifts to sleep amidst a pungent cloud of alcohol vapors, you think of the advice he provided.\n\nEager to experiment with your new mining technique, you leave the sleeping man laying where he is.>", objectives = "Bring Franklin The Drunk a drink he likes to learn his mining secrets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48771] = { id = 48771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herb 07 - Rare - Rank 2 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.You will learn:", objectives = "Find someone on Argus who might be able to train you on how to handle Astral Glory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48772] = { id = 48772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herb 07 - Rare - Rank 3 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.You will learn:", objectives = "Find someone on Argus who might be able to train you on how to handle Astral Glory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48773] = { id = 48773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Papers, Please", description = "All this legwork will be for nothing if we can't show Katherine hard proof linking the Ashvane Company to the freebooters here in Freehold.\n\nAshvane might have been careful to encrypt their books, but I doubt the dockmaster here has any reason to be so secretive.\n\nCheck his office and find us something--anything--that connects him to Ashvane.", progress = "Lady Katherine is as stubborn as a whale shark. She won't buy our story without proof.", completion = "Nice work! This is undeniable proof that Priscilla has been selling weapons to pirates.\n\nIt's high treason!", objectives = "Collect the Dockmaster's Records.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48774] = { id = 48774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Beatings Will Continue", description = "Ain't seen you before. You a mercenary? \n\nI got some guys need roughin' up.\n\n<The grizzled woman spits through a gap where her front tooth should be.>\n\nEver since Harlan started fancyin' himself an admiral, his Irontide guppies been struttin' around like they own the place. Forcin' other crews to swear loyalty to Harlan, beatin' on us what can't defend ourselves.\n\nFreehold was never a safe town, but at least it was free.\n\n<She runs her tongue along the gap in her teeth.>\n\nBastards.", progress = "Well is you a merc or isn't you? Get to merc'in!", completion = "Haha!\n\n<Geraldine spits again out of her tooth gap.>\n\nHad it comin' they did!", objectives = "Slay 5 Irontide Ruffians and 2 Irontide Overseers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48776] = { id = 48776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rig Robbing", description = "I'm out here tryin' to enjoy my break, but I ran outta hooch.\n\nGot some grog hidden in the water just off the dock, stashed in a crate tied up to some of the rigging. \n\nDo me a favor and fetch it, will ya? Rigging's pretty tangled so you might have to pull in a few lines before you get the right one.\n\nI'd do it myself, but if they see me they're gonna force me back to work unloadin' them new weapons.", progress = "You get my stash?", completion = "Ah, there she is! Good show.\n\nWhaddya say to a toast?", objectives = "Use the Tangled Rigging to collect the \"Sea Dog\" Grog.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48777] = { id = 48777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den of Fiends" }
quests[48778] = { id = 48778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stone Soup", description = "On the surface of the rock you find carvings of what you make out to be ingredients.\n\nIf you find the ingredients, perhaps you can make the troggs' soup for yourself.", progress = "The flavor of the soup doesn't seem quite right. It must be missing ingredients.", completion = "The soup has somehow taken on a somewhat floral quality. It feels well-balanced on the tongue and goes down very smoothly.\n\nThis may be, in fact, the most delicious cuisine you have ever tasted.", objectives = "Collect the ingredients for Stone Soup in Mistfall Cleft.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48780] = { id = 48780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gladius" }
quests[48783] = { id = 48783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nobody Expects Them" }
quests[48790] = { id = 48790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Goods", description = "It was brought to my attention recently dat many of our supplies went missing overnight.\n\nI suspected dat Tongo's crew was behind de theft, but we didn't have de strength or numbers needed to confront dem.\n\nI want you to search de hideout for signs of our missing supplies. If dere's anything left when you arrive, bring it back here and I'll make sure you're compensated.\n\nIf we're going to survive Mojambo's assault we're going to need those stolen supplies back as soon as possible.", completion = "You've located de supplies and dey appear mostly intact! You have done a great service for our tribe, {name}.", objectives = "Recover 6 stolen supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48792] = { id = 48792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Menace to Society", description = "These troggs are a menace to the whole area! They raid camps and caravans and eat the livestock when they come down from their caves. The kids being up there might set them off!\n\nSlay some of those troggs before they decide to cause trouble.", progress = "There are a lot of troggs around. More than I expected to see.", completion = "You look like you've been in a fight. Did you introduce those troggs to the business end of your weapon?\n\nThat's what I would have done! Give 'em a good right hook! And then a left! Pow! Bam!\n\nI bet they're sorry for messing with you!", objectives = "Kill 10 Bonegnasher troggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48793] = { id = 48793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Adventurer's Society", description = "Thank the Light!\n\nI was taking care of my grandson and his friends. I told them to play quietly while I took a nap. When I woke up they'd left a note saying they were 'Going on an Expedition'. They think they'll find Titan relics in the trogg caverns!\n\nThey're too young to fight troggs and I'm too old! My bad knee almost gave out getting here.\n\nYou look strapping. Find my grandson and the rest of the 'Adventurer's Society'. Send them home!", progress = "Hey! You found our stuff!", completion = "Nigel's grandpa is nice and all, but he'd have slowed us down! Adventure, fortune and fame awaited!\n\nMaybe we should have brought a weapon or something though.", objectives = "Look for signs of the children.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48799] = { id = 48799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fuel of a Doomed World", description = "There is a rare and precious resource to be found in these wastes, {name}.\n\nArgunite was once abundant on Argus. Its magical properties helped eredar civilization thrive. Far better for us to make use of its power than the Legion.\n\nSeek out all the pristine argunite you can, champion. Every bit you recover will aid our cause.", progress = "Victory requires every resource we can muster.", completion = "A good start, hero. There is plenty more where that came from.", objectives = "Collect 50 Pristine Argunite from Invasion Points, Rare encounters, or treasure chests on Argus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48800] = { id = 48800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mark of the Bat", description = "Dere are three witches in de camp who have talismans empowered by Hir'eek.\n\nI need you to get those talismans for me to use after you prove my poison works perfectly.\n\nI will use de essence of Hir'eek within de talismans to make my own poison strong enough to use against de loa.\n\nIf my poison doesn't work... well, I do not want to think about dat. It will work, because we need it to. \n\nJust go get de talismans. I will be here, hiding from de blood trolls.", progress = "Did you get de talismans? We don't have much time until Hir'eek comes back out to try and eat us!", completion = "You did it! Just need to grind dem up like dis... and done. Either dis poison will work... or we will both be dead.", objectives = "Recover talismans from Blood Witches Vashera, Yialu, and Zu'Anji within  Zalamar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48801] = { id = 48801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Isolating Zalamar", description = "Hir'eek, de loa of bats, has been corrupted by G'huun! We will get no help from him.\n\nWe only have one option if dey have a loa on their side... we must kill Hir'eek.\n\nIt's crazy, and we will both probably die, but I have a plan. We need to isolate dis place first.\n\nDe blood trolls have wardrummers who sound an alarm if anything happens here. We need dem gone... but you have to be sneaky about it.\n\nYou have a good disguise, so you can order de drummers to go leave their posts.", progress = "Did you take care of de wardrummers?", completion = "Hah! Now we have plenty of room to mess with dis camp. Dere will be no reinforcements from de other blood trolls.", objectives = "Order Wardrummers Saljo, Sheej, and Gix to leave their positions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48803] = { id = 48803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging a Key to the Past", description = "The armory key fragments are gathered, and the dendrite clusters should provide just enough power to reforge the key.\n\nThis should not take long... assuming it works. It has been a long time since I made one of these!", progress = "Bear with me as I finish my work.", completion = "Success! It is nice to know I haven't lost my touch.\n\nHere you go, {name}; it is as good as new.", objectives = "Watch as Gaal reforges the Armory Key.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48804] = { id = 48804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistakes Were Made", description = "My friends and I wanna be explorers so we made the Society. There are troggs here, right? So that means there's probably ancient stuff nearby!\n\nThe books say troggs like shiny things so we pooled some of our allowance and gave them gold so we could dig.\n\nIt didn't work out like we expected.\n\nI escaped but they've got my friends! I've been trying to think about how to get them out.\n\nCould you do it? We'll include you in our exploration report as an honorary member!", progress = "Hey! Are you gonna help my friends?", completion = "Yay! You saved my friends!\n\nI mean, they probably could have escaped on their own, but it was nice you could distract the troggs for 'em.", objectives = "Rescue the Adventurer's Society.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48805] = { id = 48805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Research Recovery", description = "<The discarded paper contains a list of the items the Adventurer's Society has found during the course of their 'excavation' here at the Northern Caverns.\n\nIt is unlikely they actually found relics, but there's no harm in recovering the items the kids found. At the least they're souvenirs of the adventure.>", progress = "Woah! You found our relics! Aren't they neat?", completion = "Isn't our stuff neat? We found real relics!\n\nI bet Brann Bronzebeard will be impressed. We're gonna write to him once we get back home.", objectives = "Recover the \"relics\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48808] = { id = 48808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thesis Statement", description = "My thesis!\n\nThose smelly troggs took my thesis paper and fed it to their boars! Can you believe it!?\n\nI worked forever on it! Two whole days! If I don't get it back I'm ruined! Absolutely ruined!\n\nPlease get my thesis paper back for me?", objectives = "Recover Thesis Paper Pages.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48809] = { id = 48809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
