quests[48822] = { id = 48822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48823] = { id = 48823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Projection Destruction", description = "Dis lich, Zardrax, be tryin' ta corrupt us ta join his side, {name}. I not be fallin' for it, and I know how ta be stoppin' it.\n\nHe be gatherin' power from dem mounds of skeletons. We gotta burn 'em ta cut Zardrax off a some power.\n\nI be strong in da fire mojo. I can be impartin' some of me connection to da fire to ya ta burn dem mounds.\n\nI be stayin' here with Kal'dran. I tink Zardrax be gettin' ta him.", progress = "Ya better get movin' and destroy dem skeleton mounds.", completion = "I saw dem fires burnin' from here. Zardrax gonna be hurtin' from dis one.", objectives = "Destroy 3 Skeleton Mounds with Da'jul's Fire Mojo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48824] = { id = 48824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48825] = { id = 48825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power Denied", description = "Ah! Oh, it's you, {name}. Zardrax has me on edge, saying we are all doomed, dat dere is no hope.\n\nI had a plan to stop him. All we had to do was kill a hexxer, Nana'kwug, who is helping spread Zardrax's power, and steal de fetish she is using.\n\nDen you'd give dat fetish to Da'jul and he'd use his voodoo to grant us more power.\n\nBut it is hopeless now. Maybe we should just side with Zardrax. How can we stop someting as big as dis?", progress = "Ya got dat fetish yet? Maybe Kal'dran be calmin' down when he sees we be havin' a chance ta survive.", completion = "Good job on gettin' dis fetish. Dere be a lot dat I can be doin' with dis ting.", objectives = "Defeat Hexxer Nana'kwug and recover her blood fetish.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
