quests[48837] = { id = 48837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All-Seer Xanarian" }
quests[48840] = { id = 48840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruins-Level Marketing", description = "Now dat de Goldtusk Inn be open for business, we gotta make sure everyone in Vol'dun knows about it!\n\nI think we should focus on those wagon-riding vulpera first. Dey don't even have real homes!\n\nIn fact, I saw a pack of vulpera up at de ruins to de north de other day, and dey barely had anything.\n\nTake dem dis coupon and tell dem to stop by for a free first stay.", completion = "<Kenzou looks skeptically at the leaf you handed him.>\n\nNo, I will not be going there. But are you looking for some real work?", objectives = "Deliver the Goldtusk Inn coupon to Kenzou.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48846] = { id = 48846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liquid Motivation", description = "<Zauljin motions for you to come closer. He is clearly drunk.>\n\nIf I had information concerning Mojambo...<hick!>...how much would dat be worth to you?\n\nYou don't...<hick!>...believe me? Nobody suspects a drunk. I hear all sorts of things...\n\nWhat do you have to lose? All it will cost is a bottle of...<hick!>...Zanchuli Reserve!\n\nWhaddya say, mon?", progress = "What do you have for me?", completion = "Mojambo is teaming up with an outside gang to attack us? I knew he meant business, but I didn't expect him to go dis far. We need to come up with a plan as soon as possible...", objectives = "Bring a bottle of Zanchuli Reserve to Zauljin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48847] = { id = 48847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arming the Tribe", description = "We spotted some of Tongo's gang scouting de arena while you were away. It seems dis may be de calm before de storm.\n\nWe need to get de weapons you brought back from Tongo's hideout into de hands of our fellow outcasts. Mojambo's gang could attack any minute now.\n\nWe need to be prepared. Take de weapons and get dem to de unarmed members of de tribe.\n\nIf Mojambo thinks he can raid our home without a fight, he's got another thing coming.", progress = "De time for war is nearly upon us.", completion = "It's a good thing you armed de tribe! Mojambo and his gang are attacking as we speak!", objectives = "Arm 8 Scorched Sands Outcasts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48850] = { id = 48850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tongo", description = "If Mojambo hired Tongo's gang as reinforcements, we're in even more trouble than we first thought.\n\nTongo is a cruel and sadistic marauder who takes great delight in suffering. His gang is notorious for torturing their prey.\n\nWe won't be able to defend ourselves against both gangs at once. Our only chance of survival now is to strike first.\n\nIf you take out Tongo before de ambush, Mojambo will be expecting reinforcements dat never arrive. We may be able to use dat to our advantage...", progress = "Has Tongo been defeated?", completion = "With Tongo out of de way, all we have to worry about now is Mojambo...", objectives = "Retrieve Tongo's Head.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48852] = { id = 48852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stopping Zardrax" }
quests[48853] = { id = 48853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terminal Degree", description = "That's everyone but Nigel.\n\nHe's in the big cave! I bet he went in there to look for relics, but now he's tied up!\n\nWould you save him too?", progress = "Thanks! Negotiation is a lot harder than Brann's book makes it out to be.", completion = "Thank you for saving my grandson and his friends.\n\n I'm sure they will make fine explorers when they're adults.\n\nWhich will be about the time they are no longer grounded!", objectives = "Slay Cragg the Stoneshaker and free Nigel Rifthold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48854] = { id = 48854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offer of Power", description = "Ah... a {class}. You must be {name}... I have heard whispers of your name. Maybe you are smarter than dese two.\n\nZuldazar will fall to de blood trolls. You know dis. \n\nYou can be saved, if you promise to serve me. I can give you more power than you have ever imagined.\n\nListen to what I can offer you...", completion = "Zardrax be temptin' us ta join him, but dat ain't gonna work. We gonna stop dis lich and anyone else who wants ta help da blood trolls!", objectives = "Listen to Zardrax's speech.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48855] = { id = 48855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Humbling the Terrors", description = "When we first got here, I be findin' a whole buncha problems on da other side a Zardrax's barrow. \n\nDere be dese monstrous zombies walkin' around da area. We gotta take 'em down ta make sure dey don't get ta Zuldazar.\n\nI used me voodoo ta be modifyin' dat fetish ya just found. Use dis new fetish ta weaken and kill dem zombies.", completion = "Good work. We be savin' lots a people in Zuldazar from bein' crushed by dem zombies.", objectives = "Defeat 3 Reconstructed Terrors by weakening them with the Modified Blood Fetish.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48856] = { id = 48856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conduit Interruption", description = "Dere be skeletons dat be funnelin' blood magic inta Zardrax's barrow. Me guess be Zardrax created dem ta help gather more power.\n\nYa gotta kill dese skeletons if ya want any shot at killin' dis lich. He should be gettin' weaker if he not be havin' dem as a source a power.\n\nI be stayin' here in da meantime ta be watchin' our backs, no tellin' if dere be blood trolls comin' ta attack us.", completion = "I can be tellin' from here dat Zardrax's power be gettin' weaker. We close ta endin' dis.", objectives = "Defeat 8 Zardrax Conduits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48857] = { id = 48857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Hope is Lost", description = "I am not doing dis anymore! You and Da'jul are WRONG! Dere is no stopping Zardrax!\n\nI am leaving, and you cannot stop me. Zardrax will save us all from destruction and give us new power!", progress = "Did ya find where Kal'dran ran off ta?", completion = "We got no time ta be mournin' Kal'dran. He made his choice, so now we be makin' ours ta defeat Zardrax.", objectives = "Calm down Kal'dran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48858] = { id = 48858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
