quests[48860] = { id = 48860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48864] = { id = 48864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Broken Blacksmith", description = "{class}, I believe this may be a piece of the key to the Armory of the Triumvirate. We locked it behind us as we made our escape from Argus. The last time I saw it, my second in command, Atalaa, was leading a force to secure the armory. That was so long ago...\n\nI cannot be certain, but there may be another who would know. The smith who forged the key was called Gaal. With the reports of broken surviving on Krokuun, he may still live.", completion = "I am glad to hear Fareeya is well.\n\nShe is right... this is a fragment of the armory key I forged her so long ago.", objectives = "Find the blacksmith Gaal.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
