quests[48866] = { id = 48866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void Warden Valsuran" }
quests[48867] = { id = 48867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chief Alchemist Munculus" }
quests[48869] = { id = 48869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Payback's a Lich", description = "We can't be focusin' on da loss of Kal'dran. He be givin' up hope, and dat be someting we not gonna do.\n\nDis be da time ta strike at Zardrax. His power be waning. \n\nGo inta da heart of his barrow and destroy him, once and for all. Dat should show dem blood trolls who dey messin' with!\n\nI'd help ya, but I be weakened from da blood trolls dat be attackin' me when ya were gone. \n\nDon't worry 'bout me, I can still be handlin' dem animals if dey come back.", progress = "We need ta destroy Zardrax. Dis be our chance!", completion = "Ya did it! Zardrax be gone, and now da blood trolls be losin' a major source of their power.\n\nI be makin' my way back ta da camp ta let Princess Talanji know 'bout Kal'dran.\n\nShe deserves ta be knowin' dat he lost hope in our cause... might be good ta be seein' if anyone else is havin' doubts about what we be doin'.", objectives = "Defeat Zardrax the Empowerer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48870] = { id = 48870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Many-Faced Devourer", description = "<The scroll's runes shift to a more intelligible form.>\n\nAn effigy. The Many-Faced One requires it.\n\nSteal from the Imps. Steal from the Fiends. Steal from the Ur'zul.\n\nHe comes.", objectives = "Collect bones from the Antoran Wastes to form a bone effigy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48871] = { id = 48871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue the Relics", description = "According to the information you brought us, we should be adding those relics to our collection.\n\nExplore the ruins and see if you can find any of these \"tokens of affection\" the sethrak may have left for their Keepers. \n\nBetter we find hands that will cherish them, than ones that will destroy.\n\nPlus, add a little time, and anything becomes interesting... to the right people.", progress = "Did you find the relics?", completion = "Perfect. The power of nostalgia is fascinating. These relics will hold great sentimental value. The monetary value won't be bad, either.", objectives = "Collect 8 Ahjani Relics in Zul'Ahjin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48872] = { id = 48872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expedite the Excavation", description = "Everywhere we go, there they are. Sethrak. And it's never the ones you want to see.\n\nIt seems they are looking for some key. With this new information, I do not think they are looking in the right place.\n\nReally, as entertaining as it is to confound them, we need to wrap up our work here and move on.\n\nIf you could remove some of them, it would greatly help our crew!", progress = "I need to mark this down. \n\nHow many sethrak have you killed?", completion = "Well done! They must be so irritated. This is great fun!", objectives = "Slay 12 Sethrak in the Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48873] = { id = 48873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grizzly End", description = "This lodge serves as the largest supplier of furs and leather to Boralus.\n\n<Kennings puffs out his chest a bit.>\n\nAnd as its proprietor, it is my duty to ensure every request is met on time. With recent delays, I've decided to take a trip out here to see if the Holtons need my assistance.\n\nWe could use any available hands! Take this knife and bring back some pelts from the bears in the nearby pass.", progress = "I see that Lord Kennings' idea of assistance hasn't changed since his last visit.", completion = "These furs appear to be in fine shape. Your skills should easily make up for any setbacks caused by 'accidents'.", objectives = "Skin 6 Monstrous Grizzlies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48874] = { id = 48874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pardon Our Rust", description = "The traps we've set up in the field require routine maintenance checks. Some of them are fairly old and will spring at incorrect times. If only we could get more funding for these sort of supplies. \n\n<The huntmistress glances towards Lord Kennings.>\n\nWhile you're out hunting, could you reset any sprung ones that you find?", completion = "It seems that you still have all of your limbs attached, and here I was hoping that I could talk Kennings into buying us new traps. Fair work.", objectives = "Arm 5 Bear Traps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48875] = { id = 48875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mix It Up" }
quests[48876] = { id = 48876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48877] = { id = 48877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48878] = { id = 48878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48879] = { id = 48879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hunt for Hawk Eggs", description = "Before Alanna sends us on our grand hunt, there is something more immediate demanding our attention...\n\nI'm absolutely famished! No good man can hunt on an empty stomach.\n\nThere are hawks in the area, which means that there are also hawk eggs. I'm not sure how well they'll do in an omelet, but I'm always one for a culinary adventure!\n\nGood {class}, could you bring back a few before we get started?", progress = "Have you found enough eggs yet? You know what those small goblins say, time is money!", completion = "Fantastic! Here's hoping that hawk eggs aren't too gamey...", objectives = "Gather 12 Hawk Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48880] = { id = 48880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mean Gulls", description = "Must... catch... Need more...\n\nThe gulls... they bite... scratch... take...\n\nI need them gone... but... I must... catch...", completion = "The gulls are... no more...\n\nNow... I can catch more...\n\nYes... catch more...", objectives = "Kill 10 Territorial River Gulls near Mudfish Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48881] = { id = 48881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Reel Deal", description = "<These fishing rods must have been left behind when Art moved from the beach.  Most of them seem to have bites.\n\nMaybe you should reel them up and see what's hooked?>", completion = "<That looks like the last of Art's rods.\n\nYou manage to salvage some of Art's bait with your catch. \n\nWaste not, want not>", objectives = "Reel in 5 Fishing Rods in Snapclaw Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48882] = { id = 48882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Like Fish Guts and I Cannot Lie", description = "<It looks like some of the fish the gulls have been stealing from Art are still intact.\n\nHe'd probably be happy to get the innards from these as well.>", progress = "What's... this?", completion = "Yes... yeeesss...\n\nMore entrails... more innards... only the best...", objectives = "Collect 9 Mudfish Innards from Intact Mudfish near Mudfish Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48883] = { id = 48883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Big Gulls Won't Die", description = "Still one more... takes my bait... my fish...\n\nMy finger...\n\nKill him... you will be... rewarded...", progress = "Must... catch...", completion = "Is he dead?\n\nYes... now I can catch... and gut... and catch...\n\nMore entrails... only the best for the sisters...", objectives = "Kill Brinebeak in Mudfish Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48884] = { id = 48884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48885] = { id = 48885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48886] = { id = 48886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48887] = { id = 48887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleanse the Mind", description = "If you wish to invite Akunda into your mind, it can't be bogged down by fear or regret. \n\nMeditate at de Shrine of Thunder and confront whatever demons linger in de dark recesses of your mind.", progress = "Some who meditate at de shrine hear de voice of de loa himself, though most only hear silence or de sounds of their failings.", completion = "I can tell you found success. You are at peace.", objectives = "Meditate at the Shrine of Thunder and confront your inner demons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48888] = { id = 48888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Springs Eternal", description = "Water is a sacred resource in dese dunes, but those within dis temple never know thirst. \n\nAkunda commands de storm, allowing de nearby spring to never run empty. \n\nUnfortunately, our eternal water source attracts a variety of animals dat are a plague upon our temple. \n\nRid de valley of their presence before you return.", completion = "De spring is a gift from de loa and must be preserved at all costs.", objectives = "Kill Redrock Scavengers and Redrock Howlers near The Eternal Spring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48889] = { id = 48889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repairing the Past", description = "Dis explains why de loa has been silent. Akunda himself has forgotten who he is!\n\nSomeone or something must be abusing his power. \n\nWe won't know how to help without speaking to de loa.\n\nI can perform a ritual dat may repair Akunda's mind, but it is not without risk.", completion = "I seek your help, {name}.", objectives = "Protect Meijani while she repairs Akunda's mind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48890] = { id = 48890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Be a Blood Troll", description = "You will have to blend in if you don't want anyone getting suspicious. This won't be pretty.\n\nDere are drudges around de camp who have been tied up as part of a ritual. Dey get beaten as a test to make dem stronger.\n\nAny who fail de ritual are sacrificed. De ones who succeed are allowed to fight de Zandalari.\n\nIf you are going to blend in, you need to \"test\" dese drudges as part of de ritual. It's weird, but dat's how dey work.", progress = "It is not a pretty task, but dese trolls are not our allies.", completion = "Good work, nobody suspects a thing. Did any of dem crack under de pressure?", objectives = "Test 5 Unproven Drudges.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48894] = { id = 48894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial of Truth", description = "Those within our temple have left their past lives behind. They devote themselves entirely to Akunda. \n\nDis final test is perhaps de most important. \n\nDis is de moment of truth. \n\nYou will speak your name, as you will be known from dis day forth.", completion = "You have proven worthy of entering our temple, Akunda.", objectives = "Speak your name to Akunda the Exalted.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48895] = { id = 48895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Perfect Offering", description = "Dis offering is all dat I have to my name, but it wouldn't be right for me to use it for myself when I know your friend is in danger. \n\nShe saved my life, now I can save hers.\n\nTake de offering. Don't make me ask twice.", progress = "Do you come bearing gifts to our loa?", completion = "Dis is a generous offering, but a gift alone isn't enough to enter our temple. \n\nRedemption can't be bought, it must be earned. \n\nLucky for you, dere is much work to be done.", objectives = "Deliver the offering to Akunda the Exalted at the Temple of Akunda.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48896] = { id = 48896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knowledge of the Past", description = "An old friend of mine came to de sands willingly to gain knowledge of de past. \n\nIf anyone can locate dis weapon, it would be Julwaba. \n\nLast I heard, she planned to excavate de ruins surrounding de great pyramid.", progress = "How did Jarka'zet's men know where we'd be?", completion = "It's clear dat Jakra'zet won't stop until I'm dead.", objectives = "Travel with Meerah's Caravan in search of Julwaba.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48897] = { id = 48897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bargain is Struck", description = "Now dat you have declared a patron loa for your time here in Zuldazar, you should inform de king of your decision.\n\nHe will appreciate dat you chose to follow de mighty Gonk.", completion = "So, you have chosen de path of Gonk. May de loa forever reveal de tracks of your enemies.\n\nFor myself, I follow Rezan, de devilsaur loa of kings. He and I have not spoken for many years, though.\n\nPerhaps I shall pay him a visit one of dese days.", objectives = "Speak with King Rastakhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48898] = { id = 48898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lucky Charm", description = "My daddy would never admit it, but he's really superstitious. I don't think he'll ever feel safe on a horse unless he has a lucky charm!\n\nI heard about a fox somewhere around here that's been eating a lot of chickens, and escaping everybody trying to catch him. I bet he's really lucky! Maybe if you got his tail and gave it to my dad, he'd feel lucky too!", progress = "Tails are real lucky, {name}. I think this one will give my dad heaps of courage!", completion = "I think I can feel the luck too!", objectives = "Collect Lucktail's Tail from Lucktail in Rockskip Falls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48899] = { id = 48899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety First", description = "The connection between horse and rider is fascinating to me, and I will never truly understand until I experience it.\n\nBut, well, you know... armor! How could I possibly even think to mount one of these beauties without some proper protection?\n\nI saw some waterfalls nearby. There must be shells near the banks of its pools! Would you entertain an old Tortollan by collecting some for his safety?", progress = "Protection, yes. Can't put yourself in a dangerous situation without the proper protection!", completion = "Ah yes, these shells will help keep me well safeguarded!", objectives = "Collect 8 Durable Seashells in Rockskip Falls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48902] = { id = 48902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monstrous Energy", description = "Have you ever heard about eel juice? I don't know if it's safe for {race}s like you, but tortollans love it! It gives us a burst of energy, and puts a spring in the step of even the oldest tortollan.\n\nI saw some eels to the north of the estate when we were traveling. Can you go collect some of their venom for my dad?", progress = "My dad will be so excited when he sees his favorite drink!", completion = "Oh boy oh boy! He's gonna be pumped!", objectives = "Collect 6 Pulsating Extract from Venomscale Slitherers in Rockskip Falls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48903] = { id = 48903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Perfect Horse, of Course", description = "With all that you've collected for me... I guess it is time to mount, isn't it?\n\nHoo! I haven't felt such nerves for three hundred years! Would you mind assisting me in finding a suitable equine partner? I could not trust myself to make the decision alone!", progress = "My dad thinks horses can have lots of personalities, just like us. We gotta find him the perfect horse for his first ride!", completion = "He's on! He's on!\n\nDon't worry, {name}. I'm sure he'll be fine! Thanks for all of your help!", objectives = "Assist Majo in choosing and mounting a horse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48904] = { id = 48904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take the Bait", description = "The bait... almost gone now... must catch...\n\nThe crabs... find them... get more...", progress = "Almost gone...", completion = "Yes... more meat!\n\nI must not... can not... stop!", objectives = "Collect 15 Snapclaw Meat from Snapclaw crabs in Snapclaw Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48905] = { id = 48905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unappreciated Scrolls", description = "Since you're here in Natha'vor, you might as well help out the rest of the pilgrimage with a problem.\n\nThese trolls have stolen several of our scrolls. Why they would, I have no idea, I doubt they're smart enough to even read.\n\nI want you to get them back. I'm not young anymore, I can't just be casting magic off the top of my head! \n\nEspecially healing magic... which I'm sure Shoak is going to need when you rescue his dumb shell.", objectives = "Recover 8 Tortollan Scrolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48906] = { id = 48906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[48909] = { id = 48909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noble Responsibilities", description = "From the state of this body, I would say a beast with formidable claws or fangs ravaged this camp. You say the trail leads westward? This camp usually houses more than one of Alanna's hunters. I wonder if they are tracking the beast down as well.\n\nHurry it up! I don't want to spend the day waiting around. Track our dangerous quarry!", completion = "Thank you for dealing with the threat. I'll see that the men who died out there have a proper send off.", objectives = "Track and kill the murdering monster.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48910] = { id = 48910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplying Krokuun", description = "This desolate place offers little for my people. Every hour is spent scraping together enough to survive. If I had more supplies, I could offer you another ridgestalker.\n\nWhat say you, offworlder?", progress = "This desolate place offers little for my people. Every hour is spent scraping together enough to survive. If I had more resources, I could offer you a ridgestalker.\n\nI can only part with a Krokul-Ridgestalker for this few resources once per week. Next week, I will offer you this trade again.", completion = "What say you, offworlder?", objectives = "Collect 150 Order Hall Resources.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48911] = { id = 48911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void Inoculation", description = "All entities touched by shadow leave behind traces of void when they are defeated, If you collect enough in your travels through the city, return to me, and I will distill it into its undiluted form. \n\nWe can save more of my kin.", progress = "If you bring the necessary supplies, I can begin the distillation process, {name}.\n\nI can only free one of the Void-Touched with this few resources once per week.", completion = "Another soul freed from the cruelty of the void.", objectives = "Collect 100 Fragments of Condensed Void.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48912] = { id = 48912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplying the Antoran Campaign", description = "The Legion requires raw materials from conquered words to fuel their crusade. Travel through Legion portals, destroy demons you encounter, and deny them the resources required to maintain their war machine.", progress = "The campaign against the Legion has taxed our existing resources heavily. Bring me supplies and I will place a lightforged under your command.\n\nI can only spare a lightforged for this few resources once per week.", completion = "A lightforged soldier can wade through a sea of demons. They will serve you well.", objectives = "Complete 10 Invasion Points.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48913] = { id = 48913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monalite Deposit - Rank 1 Unlock", description = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish.\n\nAs it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.You will learn:", objectives = "Find someone on Argus who might be able to train you on how to handle Astral Glory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
